def link_existing_applications_to_companies(apps, schema_editor):
    Application = apps.get_model("applications", "Application")
    Company = apps.get_model("applications", "Company")
    database = schema_editor.connection.alias
    known_companies = {}

    for application in Application.objects.using(database).exclude(owner_id=None).iterator():
        company_name = application.company_name.strip()
        if not company_name:
            continue

        key = (application.owner_id, company_name.casefold())
        company = known_companies.get(key)
        if company is None:
            company, _created = Company.objects.using(database).get_or_create(
                owner_id=application.owner_id,
                name=company_name,
                defaults={"country": application.country},
            )
            known_companies[key] = company

        Application.objects.using(database).filter(pk=application.pk).update(
            company_id=company.pk,
        )


